<template><span><el-button v-if="canAssign" type="text" @click="open">指定采购员</el-button><el-dialog v-if="visible" title="指定订单责任采购员" :visible.sync="visible" append-to-body width="min(500px, 95vw)"><p>订单：{{ order.order_no }}</p><el-select v-model="buyerId" clearable filterable remote :remote-method="search" :loading="loading" placeholder="输入姓名或编码查找" style="width:100%"><el-option v-for="b in buyers" :key="b.id" :value="b.id" :label="b.name+' / '+b.user_code"/></el-select><p>仅可分配启用的采购员/采购经理；清空选择可取消分配。此操作只确定订单归属，不授予额外系统权限。</p><span slot="footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存归属</el-button></span></el-dialog></span></template>
<script>
import {api} from '../api/client';
export default {props:{order:Object},data:()=>({visible:false,buyerId:'',buyers:[],loading:false,saving:false,requestId:0}),computed:{canAssign(){return ['admin','procurement_manager'].includes(this.$store.state.user.role);}},methods:{open(){this.buyerId=this.order.buyer_id||'';this.visible=true;this.search('');},async search(keyword){const id=++this.requestId;this.loading=true;try{const r=await api.get('/staff-users',{params:{keyword,status:'active',page:1,page_size:100,unfiltered:true}});if(id===this.requestId)this.buyers=r.data.items.filter(b=>['buyer','procurement_manager'].includes(b.role));}catch(_){this.$message.error('采购员列表加载失败');}finally{if(id===this.requestId)this.loading=false;}},async save(){this.saving=true;try{await api.put('/analytics/order-buyers/'+this.order.id,{buyer_id:this.buyerId||null});this.visible=false;this.$message.success('订单归属已更新');this.$emit('saved');}catch(e){this.$message.error(e.response?.data?.detail||'分配失败');}finally{this.saving=false;}}}};
</script>
